  "signal_basis": {
    "component_id": "C041.signal_basis",
    "value": "The release test yields a sufficiently precise estimate of the first-publication effect to rule out the predefined minimum worthwhile improvement.",
    "scope": "The selected intervention, assessed over follow-up spanning an intended roster opportunity; failure to benefit does not establish that its proposed mechanism is absent.",
