      "rationale": "These spans supply the predefined benefit threshold, follow-up, measured effect and uncertainty, precise exclusion condition, and limit on interpreting intervention failure."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C041.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
